#include <bits/stdc++.h>
using namespace std;

template<class T> void log_value(const char *label, T val) { cerr << label << '=' << val << endl; }
template<class T, class... Args> void log_value(const char *label, T val, Args... args) {
  while(*label != ',') cerr << *label++;
  cerr << '=' << val << ','; log_value(label + 1, args...);
}
template<class T> ostream &operator<<(ostream &os, vector<T> v) {
  os << "["; for (auto &x : v) os << x << ","; return os << "]";
}
template<class L, class R> ostream &operator<<(ostream &os, pair<L, R> p) {
  return os << "(" << p.first << "," << p.second << ")";
}
#define debug(...) log_value(#__VA_ARGS__, __VA_ARGS__)

vector<long long> pattern;
long long process(long long n, long long l) {
  long long div = n / pattern[l];
  n %= pattern[l];
  if (n == 0) return div * l;
  return div * l + min(l + process(pattern[l] - n, l - 1), process(n, l - 1));
}

int main() {
  ios::sync_with_stdio(false); cin.tie(0);
  long long t = 1, n;
  pattern.resize(17);
  long long base = 0;
  for (int i = 0; i < 17; ++i) {
    pattern[i] = base;
    base = base * 10 + 1;
  }
  while (t--) {
    cin >> n;
    cout << process(n, 16);
  }
}
